class Singleton:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(Singleton, cls).__new__(cls)
        return cls._instance

class Subject:
    def __init__(self):
        self._observers = []

    def subscribe(self, observer):
        self._observers.append(observer)

    def notify(self):
        for observer in self._observers:
            observer.update()

class Strategy:
    def calculate(self, a, b): pass

class Addition(Strategy):
    def calculate(self, a, b): return a + b

class Calculator:
    def set_strategy(self, strategy):
        self.strategy = strategy
    def calculate(self, a, b):
        return self.strategy.calculate(a, b)

class Coffee:
    def cost(self): return 2.0
    def description(self): return 'Simple Coffee'

class MilkDecorator:
    def __init__(self, coffee):
        self._coffee = coffee
    def cost(self): return self._coffee.cost() + 0.5
    def description(self): return self._coffee.description() + ', Milk'

class ShapeFactory:
    def create_shape(self, shape_type):
        if shape_type == 'Circle':
            return Circle()
        elif shape_type == 'Square':
            return Square()
        raise ValueError('Unknown shape type')
